```{.r .cell-code}
P <- cached("cv_stlsq.rds", cross_validate(Theta, tr, fit_stlsq))
days <- c(35, 50, 63, 84, 99)       # array index; day after sowing = index + 14

scores <- function(d) {
  s <- rank_scores(P[, , d], tr$Y[, , d])
  data.frame(das = d + tr$das0 - 1, rho = mean(s$rho), top10 = mean(s$top))
}
out <- do.call(rbind, lapply(days, scores))
out[, c("rho", "top10")] <- round(out[, c("rho", "top10")], 3)
out
```
