## Python

```python
P = cross_validate(Theta, tr, fit_stlsq)
days = [49, 64, 77, 98, 113]                       # days after sowing

def scores(day):
    i = day - tr.das0
    rho, top = rank_scores(P[:, :, i], tr.Y[:, :, i])
    return day, rho.mean().round(3), top.mean().round(3)

out = pd.DataFrame([scores(day) for day in days],
                   columns=["das", "rho", "top10"])
print(out)
```

